def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    def _expand_env(obj):
        if isinstance(obj, dict):
            return {k: _expand_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    configs = {}
    errors = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to read file: {exc}",
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            errors.append(record)
            continue

        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext == '.toml':
                if toml is None:
                    raise ImportError("toml module not available")
                cfg = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("yaml module not available")
                cfg = yaml.safe_load(raw)
            elif ext == '.json':
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported file extension: {ext}")
        except Exception as exc:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse file: {exc}",
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            errors.append(record)
            continue

        if resolve_env:
            try:
                cfg = _expand_env(cfg)
            except Exception as exc:
                record = logging.LogRecord(
                    name=fname,
                    level=logging.ERROR,
                    pathname=fname,
                    lineno=0,
                    msg=f"Failed to expand environment variables: {exc}",
                    args=None,
                    exc_info=(type(exc), exc, exc.__traceback__)
                )
                errors.append(record)
                continue

        if overrides:
            if isinstance(cfg, dict):
                cfg.update(overrides)
            else:
                record = logging.LogRecord(
                    name=fname,
                    level=logging.ERROR,
                    pathname=fname,
                    lineno=0,
                    msg="Overrides provided but configuration is not a dict",
                    args=None,
                    exc_info=None
                )
                errors.append(record)

        configs[fname] = cfg

    return configs, errors

