    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result: Dict[str, str] = {}
    try:
        data = json.loads(document)
        # JSON format
        result["subject"] = data.get("subject", "")
        result["aliases"] = data.get("aliases", [])
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel", "")
            href = link.get("href", "")
            if rel == "self":
                result["self_url"] = href
            elif rel == "hcard":
                result["hcard_url"] = href
            elif rel == "profile":
                result["profile_url"] = href
            elif rel == "public-key":
                result["public_key"] = href
            elif rel == "lrdd":
                result["lrdd_url"] = href
            else:
                # store any other rels
                result[rel] = href
        return result
    except (json.JSONDecodeError, TypeError):
        # Try XRD (XML) format
        try:
            root = ET.fromstring(document)
            # Helper to strip namespace
            def _strip_ns(tag: str) -> str:
                return tag.split("}")[-1] if "}" in tag else tag

            subject = ""
            aliases = []
            links = {}
            for elem in root.iter():
                tag = _strip_ns(elem.tag)
                if tag == "Subject":
                    subject = elem.text or ""
                elif tag == "Alias":
                    if elem.text:
                        aliases.append(elem.text)
                elif tag == "Link":
                    rel = elem.attrib.get("rel", "")
                    href = elem.attrib.get("href", "")
                    if rel:
                        links[rel] = href
            result["subject"] = subject
            result["aliases"] = aliases
            for rel, href in links.items():
                if rel == "self":
                    result["self_url"] = href
                elif rel == "hcard":
                    result["hcard_url"] = href
                elif rel == "profile":
                    result["profile_url"] = href
                elif rel == "public-key":
                    result["public_key"] = href
                elif rel == "lrdd":
                    result["lrdd_url"] = href
                else:
                    result[rel] = href
            return result
        except ET.ParseError:
